// === Tab: mySketch ===


//try setting legs to 1000, length of leg to 8, strokeweight to 1 and see what happens (its not as laggy as you'd think)

//also looks cool with around 40 legs and a leg length of about 50 and thickness of 10
var NumOLegs = 40;

const g = -9.81
var x = [];
var y = [0];
	var a = []; //leg angle
var increase = [];
var L = 50;//Length of a leg
var totalX = [];
var totalY = [];
function setup() {
	createCanvas(500,500);
	background(100);
	for(var rep = 0;rep<=NumOLegs-1;rep++){
	x.push(0);
		y.push(0);
		a.push(1);
		increase.push(random(-0.15,0.15));
	}
}

function draw() {

	background(120,163,160);
	translate(250,250);
		strokeWeight(10);//thickness
	for(var rep =0; rep<=x.length-1; rep++){ //loops through the variables of each leg
		a[rep]+=increase[rep];
		x[rep] = (cos(a[rep])*L);
		y[rep] = (sin(a[rep])*L);

		if(rep>0){
			//adds the x values together
				totalX.push(x[rep]+totalX[rep-1]);
				totalY.push(y[rep]+totalY[rep-1]);
		}else if (rep == 0){
					totalX.push(x[0]);
				totalY.push(y[0]);
				}
			stroke(220,255-(255/NumOLegs)*rep,255-((255/NumOLegs)*(rep/3)));
				if(rep>=1){
		//		print(rep + ", " + totalX[rep] + ", " + totalX[rep-1] + ", " + x);
		line(totalX[rep-1],totalY[rep-1],totalX[rep],	totalY[rep]);
				}
	}

	stroke(255-(255/NumOLegs));
	line(0,0,x[0],y[0]);
			totalX.length=0;
		totalY.length=0;
}

